const { getApps, initializeApp, cert } = require("firebase-admin/app");
const { getAuth } = require("firebase-admin/auth");

function getAdminApp(){
  if (getApps().length) return getApps()[0];
  const projectId = process.env.FIREBASE_PROJECT_ID;
  const clientEmail = process.env.FIREBASE_CLIENT_EMAIL;
  const privateKey = (process.env.FIREBASE_PRIVATE_KEY || "").replace(/\\n/g, "\n");
  if (!projectId || !clientEmail || !privateKey) throw new Error("Firebase Admin environment variables are missing");
  return initializeApp({ credential: cert({ projectId, clientEmail, privateKey }) });
}

const TESTS = {
"test-01":"",
"test-02":"",
"test-03":"",
"test-04":"",
"test-05":"",
"test-06":"",
"test-07":"",
"test-08":"",
"test-09":"",
"test-10":"",
"test-11":"",
"test-12":"",
"test-13":"",
"test-14":"",
"test-15":"",
"test-16":""
};

function htmlError(res, status, title, message){
  res.status(status).setHeader("Content-Type","text/html; charset=utf-8");
  res.setHeader("Cache-Control","no-store, private");
  res.setHeader("X-Content-Type-Options","nosniff");
  res.end(`<!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#070b17;color:#fff;font-family:Arial,sans-serif}.box{max-width:520px;padding:28px;border:1px solid #334363;border-radius:20px;background:#121c34;text-align:center}h1{color:#f6c453}p{color:#b9c3d8}</style></head><body><div class="box"><h1>${title}</h1><p>${message}</p></div></body></html>`);
}

module.exports = async function handler(req,res){
  try {
    if (req.method !== "GET") return htmlError(res,405,"405","Method not allowed.");
    const id = String(req.query?.id || "").toLowerCase();
    if (!/^test-(0[1-9]|1[0-6])$/.test(id) || !TESTS[id]) return htmlError(res,404,"Test topilmadi","So‘ralgan test mavjud emas.");
    const cookie = String(req.headers.cookie || "");
    const match = cookie.match(/(?:^|;\s*)__kibo_session=([^;]+)/);
    if (!match) return htmlError(res,401,"Kirish kerak","Bu testni ochish uchun Google orqali kirishingiz kerak.");
    const decoded = await getAuth(getAdminApp()).verifySessionCookie(decodeURIComponent(match[1]), true);
    if (!decoded.uid) return htmlError(res,403,"Ruxsat yo‘q","Foydalanuvchi tasdiqlanmadi.");
    const html = Buffer.from(TESTS[id], "base64").toString("utf8");
    res.status(200);
    res.setHeader("Content-Type","text/html; charset=utf-8");
    res.setHeader("Cache-Control","no-store, private, max-age=0");
    res.setHeader("X-Content-Type-Options","nosniff");
    res.setHeader("Content-Security-Policy","default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'self'; script-src 'self' 'unsafe-inline' https://www.gstatic.com https://apis.google.com https://www.google.com/recaptcha/ https://www.gstatic.com/recaptcha/; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; img-src 'self' data: blob: https:; font-src 'self' data: https://fonts.gstatic.com https:; connect-src 'self' https://www.gstatic.com https://apis.google.com https://*.googleapis.com https://*.gstatic.com https://*.firebaseio.com https://*.firebaseapp.com https://firebaseinstallations.googleapis.com https://firebaseappcheck.googleapis.com https://securetoken.googleapis.com https://identitytoolkit.googleapis.com https://www.googleapis.com https://accounts.google.com https://www.google.com/recaptcha/; frame-src 'self' https://*.firebaseapp.com https://accounts.google.com https://*.google.com https://www.google.com/recaptcha/ https://recaptcha.google.com/recaptcha/; form-action 'self' https://accounts.google.com; worker-src 'self' blob:;");
    res.end(html);
  } catch (err) {
    console.error("Protected test error:", err);
    return htmlError(res,500,"Server xatosi","Testni yuklashda vaqtinchalik xatolik yuz berdi.");
  }
};
